            msg=entry.get("message") or {}
            sender=msg.get("from") or {}
            chat=msg.get("chat") or {}
            if (str(msg.get("text") or "").strip()=="/start "+code and
                chat.get("type")=="private" and
                isinstance(sender.get("id"),int) and
                sender.get("id")==chat.get("id") and not sender.get("is_bot")):
                return {"userid":sender["id"],"chatid":chat["id"],"offset":offset or uid+1}
        time.sleep(0.2)
    raise Blocked("pairing_timeout_no_matching_private_message")

def main():
    if os.name!="nt":raise Blocked("windows_dpapi_required")
    if not sys.stdin.isatty():raise Blocked("interactive_local_console_required")
    if store_path().exists():raise Blocked("existing_store_no_overwrite")
    print("Neur0Store Curator: local private setup.")
    print("First revoke the old published token in @BotFather: /revoke.")
    print("Do not paste the new token into any chat, issue or URL.")
