s=""""Exact ChatGPT curator registration for local Bridge.
A separate, opt-in mutation; never enable watchdog or change existing agent chats.
"""
import hashlib, json, os, sys, datetime
from pathlib import Path
from daemon import Blocked, call
from setup import BRIDGE, CURATOR_URL, CURATOR_BRANCH, CURATOR_SHA, CURATOR_ID, eligible_profile

FIELDS=("id","name","url","providerConversationId","providerProjectSlug","role","note",
    "enabled","profileId","repository","branch","gitHead","executionMode",
    "assignmentCutoverAt","predecessorUrl","chatHistory","localIdentityAliases",
    "lifecycleManagedAt","lifecycleMetadataAttachedAt","lifecycleReboundAt",
    "runtimeTargetTabId","runtimeBindingRefreshedAt","runtimeAccountMarkerHash",
    "runtimeBindingSource","projectId","laneId","resourceClass","instructionTemplateId",
    "priority","rotateWithProject")
def core(row):
    return {k:row[k] for k in FIELDS if k in row}
def checksum(rows):
    return hashlib.sha256(json.dumps(rows,sort_keys=True,ensure_ascii=False).encode()).hexdigest()

def planned():
    p=eligible_profile()
    j=call(BRIDGE+"/api/supervisor-watchdog/managed-chats",timeout=8)
    existing=[core(r) for r in j.get("chats",[])]
    if not existing: raise Blocked("no_original_managed_chats_do_not_replace")
    if len(existing)>450:raise Blocked("managed_list_capacity")
    matching_url=[r for r in existing if r.get("url")==CURATOR_URL]
    matching_id=[r for r in existing if r.get("id")==CURATOR_ID]
    expected={"id":CURATOR_ID,"name":"Owner Telegram curator","role":"owner-curator",
        "url":CURATOR_URL,"profileId":p["id"],"enabled":True,
        "repository":"foto6/boss","branch":CURATOR_BRANCH,"gitHead":CURATOR_SHA,
        "note":"Existing owner project-coordination ChatGPT chat; Telegram private ingress"}
    if matching_url or matching_id:
        if len(matching_url)!=1 or len(matching_id)!=1 or matching_url[0] is not matching_id[0]:
            raise Blocked("existing_curator_conflict")
        row=matching_url[0]
        for k in ("id","url","profileId","repository","branch","gitHead"):
            if row.get(k)!=expected[k]:raise Blocked("existing_curator_"+k+"_mismatch")
        return existing,existing,p,True
    return existing,existing+[expected],p,False

def main():
    before,after,profile,already=planned()
    print("Existing managed chats:",len(before),"; candidate:",len(after))
    print("Existing curator registration:",bool(already))
    print("ChatGPT exact profile debug port:",profile.get("debugPort"))
    print("Other agent bindings unchanged (planned).")
    if already:
        print("REGISTERED_EXACT; no write required.")
        return
    if "--apply" not in sys.argv:
        print("READ_ONLY_PREVIEW_OK; use REGISTER_CURATOR.cmd to approve a write.")
        return
    if not sys.stdin.isatty():raise Blocked("local_confirmation_required")
    if input("Type REGISTER to preserve existing chats and add only this curator: ").strip()!="REGISTER":
        raise Blocked("not_authorized")
    old2,new2,p2,already2=planned()
    if already2:
        print("ALREADY_REGISTERED; no write.")
